schema_ddl:
CREATE TABLE SALESPERSON (
    SALES_ID INT,
    NAME VARCHAR(255),
    SALARY INT,
    COMMISSION_RATE INT,
    HIRE_DATE VARCHAR(255)
);

CREATE TABLE COMPANY (
    COM_ID INT,
    NAME VARCHAR(255),
    CITY VARCHAR(255)
);

CREATE TABLE ORDERS (
    ORDER_ID INT,
    COM_ID INT,
    SALES_ID INT,
    ORDER_DATE VARCHAR(255),
    AMOUNT INT
);

counterexample:
INSERT INTO SALESPERSON (SALES_ID, NAME, SALARY, COMMISSION_RATE, HIRE_DATE) VALUES (1, 'Alice', 50000, 5, '2020-01-01');
INSERT INTO COMPANY (COM_ID, NAME, CITY) VALUES (100, 'RED', 'NYC'), (200, 'RED Corp', 'LA');
INSERT INTO ORDERS (ORDER_ID, COM_ID, SALES_ID, ORDER_DATE, AMOUNT) VALUES (1, 200, 1, '2023-01-01', 100);

